}

Method.Source:
/// <summary>
/// Sales invoice controller extension
/// </summary>
/// <returns>METSalesInvoiceControllerExt object</returns>
public static METSalesInvoiceControllerExt construct()
{
    return new METSalesInvoiceControllerExt();
}

public static void main(Args _args)
{
    SrsReportRunController formLetterController = METSalesInvoiceControllerExt::construct();
    METSalesInvoiceControllerExt controller = formLetterController;
    controller.parmReportName(ssrsReportStr(METSalesChargeOnly, Report));
    controller.parmArgs(_args);
    controller.parmShowDialog(false);
    controller.parmLoadFromSysLastValue(false);
    controller.startOperation();
}
